# ==============================================================================
# SCRIPT 1: OTIMIZACAO DO WINDOWS (DEBLOAT & LATENCIA)
# Atualizado e limpo - Sem referencias externas ou promocoes de terceiros
# Substitui o Helium pelo Brave Browser com politicas de alto desempenho
# Totalmente compativel para execucao direta via:
# iwr 'https://raw.githubusercontent.com/<USER>/<REPO>/main/1_Otimizar_Windows.ps1' -useb | iex
# ==============================================================================

# Execucao automatica como Administrador
If (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]"Administrator")) {
    Start-Process PowerShell.exe -ArgumentList ("-NoProfile -ExecutionPolicy Bypass -File `"{0}`"" -f $PSCommandPath) -Verb RunAs
    Exit
}

$Host.UI.RawUI.WindowTitle = "Otimizacao do Sistema (Administrador)"
$Host.UI.RawUI.BackgroundColor = "Black"
$Host.PrivateData.ProgressBackgroundColor = "Black"
$Host.PrivateData.ProgressForegroundColor = "White"
Clear-Host

# Verificacao de conexao com a Internet
if (!(Test-Connection -ComputerName "8.8.8.8" -Count 1 -Quiet -ErrorAction SilentlyContinue)) {
    Write-Host "Conexao com a Internet necessaria para baixar os componentes oficiais atualizados.`n" -ForegroundColor Red
    Pause
    exit
}

$progresspreference = 'silentlycontinue'

Write-Host "=====================================================" -ForegroundColor Cyan
Write-Host "    INICIANDO PROCESSO DE OTIMIZACAO DO WINDOWS     " -ForegroundColor Cyan
Write-Host "=====================================================`n" -ForegroundColor Cyan

# ------------------------------------------------------------------------------
# 1. PREPARACAO DOS ARQUIVOS LOCAIS PARA AS ETAPAS SEGUINTES
# ------------------------------------------------------------------------------
Write-Host "[1/7] Preparando arquivos necessarios para as etapas seguintes..." -ForegroundColor Yellow

$helperFiles = @("reg.reg", "settimerresolutionservice.cs", "start2.txt", "stepone.ps1", "steptwo.ps1")
$hasLocal = $false
if ($PSScriptRoot) {
    $hasLocal = $true
    foreach ($f in $helperFiles) {
        if (!(Test-Path (Join-Path $PSScriptRoot $f))) { $hasLocal = $false; break }
    }
}

if ($hasLocal) {
    foreach ($f in $helperFiles) {
        Copy-Item -Path (Join-Path $PSScriptRoot $f) -Destination "$env:SystemRoot\Temp\$f" -Force -ErrorAction SilentlyContinue | Out-Null
    }
} else {
    # Executado diretamente via web (iwr ... | iex): extrai pacote integrado embutido
    $b64Pkg = ''
    $zipTemp = "$env:SystemRoot\Temp\helpers_pkg.zip"
    [System.IO.File]::WriteAllBytes($zipTemp, [System.Convert]::FromBase64String($b64Pkg))
    Expand-Archive -LiteralPath $zipTemp -DestinationPath "$env:SystemRoot\Temp" -Force
    Remove-Item $zipTemp -Force -ErrorAction SilentlyContinue | Out-Null
}

# ------------------------------------------------------------------------------
# 2. INSTALACAO DO 7-ZIP (FONTE OFICIAL)
# ------------------------------------------------------------------------------
Write-Host "[2/7] Baixando e instalando 7-Zip oficial..." -ForegroundColor Yellow
$sevenZipUrl = "https://www.7-zip.org/a/7z2301-x64.exe"
try {
    $res7z = Invoke-WebRequest -Uri "https://www.7-zip.org/download.html" -UseBasicParsing -ErrorAction SilentlyContinue
    $link7z = $res7z.Links | Where-Object { $_.href -match "a/7z.*-x64\.exe$" } | Select-Object -First 1
    if ($link7z) { $sevenZipUrl = "https://www.7-zip.org/" + $link7z.href }
} catch {}

Invoke-WebRequest -Uri $sevenZipUrl -OutFile "$env:SystemRoot\Tempzip.exe" -UseBasicParsing
Start-Process -Wait "$env:SystemRoot\Tempzip.exe" -ArgumentList "/S"

cmd /c "reg add `"HKEY_CURRENT_USER\Software\7-Zip\Options`" /v `"ContextMenu`" /t REG_DWORD /d `"259`" /f >nul 2>&1"
cmd /c "reg add `"HKEY_CURRENT_USER\Software\7-Zip\Options`" /v `"CascadedMenu`" /t REG_DWORD /d `"0`" /f >nul 2>&1"

Move-Item -Path "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\7-Zip\7-Zip File Manager.lnk" -Destination "$env:ProgramData\Microsoft\Windows\Start Menu\Programs" -Force -ErrorAction SilentlyContinue | Out-Null
Remove-Item "$env:ProgramData\Microsoft\Windows\Start Menu\Programs\7-Zip" -Recurse -Force -ErrorAction SilentlyContinue | Out-Null

# ------------------------------------------------------------------------------
# 3. INSTALACAO COMPLETA DO VISUAL C++ RUNTIMES (TODAS AS VERSOES AIO)
# ------------------------------------------------------------------------------
Write-Host "[3/7] Baixando e instalando Visual C++ Runtimes (2005 ate 2022)..." -ForegroundColor Yellow
$vcUrl = "https://github.com/abbodi1406/vcredist/releases/download/v0.106.0/VisualCppRedist_AIO_x86_x64.exe"
try {
    $ghRelease = Invoke-RestMethod -Uri "https://api.github.com/repos/abbodi1406/vcredist/releases/latest" -Headers @{"User-Agent"="PowerShell"} -ErrorAction SilentlyContinue
    $asset = $ghRelease.assets | Where-Object { $_.name -like "*_x86_x64.exe" } | Select-Object -First 1
    if ($asset) { $vcUrl = $asset.browser_download_url }
} catch {}

Invoke-WebRequest -Uri $vcUrl -OutFile "$env:SystemRoot\Temp\vcredist_aio.exe" -UseBasicParsing
Start-Process -Wait "$env:SystemRoot\Temp\vcredist_aio.exe" -ArgumentList "/aiA" -WindowStyle Hidden

# ------------------------------------------------------------------------------
# 4. INSTALACAO E CONFIGURACAO DO DDU (DISPLAY DRIVER UNINSTALLER OFICIAL)
# ------------------------------------------------------------------------------
Write-Host "[4/7] Baixando e configurando Display Driver Uninstaller oficial..." -ForegroundColor Yellow
$dduSetup = "$env:SystemRoot\Temp\ddu_setup.exe"
Invoke-WebRequest -Uri "https://www.wagnardsoft.com/DDU/download/DDU%20v18.1.5.3_setup.exe" -OutFile $dduSetup -UserAgent "winget-cli" -UseBasicParsing

& "$env:SystemDrive\Program Files\7-Zip\7z.exe" x $dduSetup -o"$env:SystemRoot\Temp\ddu" -y | Out-Null

$DduConfig = @'
<?xml version="1.0" encoding="utf-8"?>
<DisplayDriverUninstaller Version="18.1.5.3">
	<Settings>
		<SelectedLanguage>en-US</SelectedLanguage>
		<RemoveMonitors>True</RemoveMonitors>
		<RemoveCrimsonCache>True</RemoveCrimsonCache>
		<RemoveAMDDirs>True</RemoveAMDDirs>
		<RemoveAudioBus>True</RemoveAudioBus>
		<RemoveAMDKMPFD>True</RemoveAMDKMPFD>
		<RemoveNvidiaDirs>True</RemoveNvidiaDirs>
		<RemovePhysX>True</RemovePhysX>
		<Remove3DTVPlay>True</Remove3DTVPlay>
		<RemoveGFE>True</RemoveGFE>
		<RemoveNVBROADCAST>True</RemoveNVBROADCAST>
		<RemoveNVCP>True</RemoveNVCP>
		<RemoveINTELCP>True</RemoveINTELCP>
		<RemoveINTELIGS>True</RemoveINTELIGS>
		<RemoveOneAPI>True</RemoveOneAPI>
		<RemoveEnduranceGaming>True</RemoveEnduranceGaming>
		<RemoveIntelNpu>True</RemoveIntelNpu>
		<RemoveAMDCP>True</RemoveAMDCP>
		<UseRoamingConfig>False</UseRoamingConfig>
		<CheckUpdates>False</CheckUpdates>
		<CreateRestorePoint>False</CreateRestorePoint>
		<SaveLogs>False</SaveLogs>
		<RemoveVulkan>True</RemoveVulkan>
		<ShowOffer>False</ShowOffer>
		<EnableSafeModeDialog>False</EnableSafeModeDialog>
		<PreventWinUpdate>True</PreventWinUpdate>
		<UsedBCD>False</UsedBCD>
		<KeepNVCPopt>False</KeepNVCPopt>
		<RememberLastChoice>False</RememberLastChoice>
		<LastSelectedGPUIndex>0</LastSelectedGPUIndex>
		<LastSelectedTypeIndex>0</LastSelectedTypeIndex>
	</Settings>
</DisplayDriverUninstaller>
'@
New-Item -Path "$env:SystemRoot\Temp\ddu\Settings" -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null
Set-Content -Path "$env:SystemRoot\Temp\ddu\Settings\Settings.xml" -Value $DduConfig -Force
Set-ItemProperty -Path "$env:SystemRoot\Temp\ddu\Settings\Settings.xml" -Name IsReadOnly -Value $true

# Evita que o Windows Update baixe drivers de video automaticamente
cmd /c "reg add `"HKLM\Software\Microsoft\Windows\CurrentVersion\DriverSearching`" /v `"SearchOrderConfig`" /t REG_DWORD /d `"0`" /f >nul 2>&1"

# ------------------------------------------------------------------------------
# 5. INSTALACAO E CONFIGURACAO DO BRAVE BROWSER (SUBSTITUINDO O HELIUM)
# ------------------------------------------------------------------------------
Write-Host "[5/7] Baixando e instalando Brave Browser (otimizado para baixa latencia)..." -ForegroundColor Yellow
$braveSetup = "$env:SystemRoot\Temp\BraveStandaloneSetup.exe"
Invoke-WebRequest -Uri "https://laptop-updates.brave.com/latest/winx64" -OutFile $braveSetup -UseBasicParsing
Start-Process -Wait $braveSetup -ArgumentList "/silent /install" -WindowStyle Hidden

# Politicas do Brave para jogos e desempenho:
# Desativa processos em segundo plano ao fechar o navegador
cmd /c "reg add `"HKLM\SOFTWARE\Policies\BraveSoftware\Brave`" /v `"BackgroundModeEnabled`" /t REG_DWORD /d `"0`" /f >nul 2>&1"
# Desativa telemetria e envio de metricas
cmd /c "reg add `"HKLM\SOFTWARE\Policies\BraveSoftware\Brave`" /v `"MetricsReportingEnabled`" /t REG_DWORD /d `"0`" /f >nul 2>&1"
cmd /c "reg add `"HKLM\SOFTWARE\Policies\BraveSoftware\Brave`" /v `"PromotionalTabsEnabled`" /t REG_DWORD /d `"0`" /f >nul 2>&1"
cmd /c "reg add `"HKLM\SOFTWARE\Policies\BraveSoftware\Brave`" /v `"BraveRewardsEnabled`" /t REG_DWORD /d `"0`" /f >nul 2>&1"
# Ativa modo de alta eficiencia de memoria
cmd /c "reg add `"HKLM\SOFTWARE\Policies\BraveSoftware\Brave`" /v `"HighEfficiencyModeEnabled`" /t REG_DWORD /d `"1`" /f >nul 2>&1"

# Desativa servicos e tarefas de atualizacao em segundo plano para evitar micro-travamentos (stutters) durante jogos
$braveServices = Get-Service | Where-Object { $_.Name -match 'Brave' }
foreach ($svc in $braveServices) {
    cmd /c "sc config `"$($svc.Name)`" start= disabled >nul 2>&1"
    cmd /c "sc stop `"$($svc.Name)`" >nul 2>&1"
}
Get-ScheduledTask | Where-Object { $_.TaskName -like '*Brave*' } | Disable-ScheduledTask -ErrorAction SilentlyContinue | Out-Null

# ------------------------------------------------------------------------------
# 6. INSTALACAO DO DIRECTX END-USER RUNTIMES (FONTE OFICIAL MICROSOFT)
# ------------------------------------------------------------------------------
Write-Host "[6/7] Baixando e instalando DirectX End-User Runtimes (Microsoft)..." -ForegroundColor Yellow
$dxFile = "$env:SystemRoot\Temp\directx_Jun2010_redist.exe"
Invoke-WebRequest -Uri "https://download.microsoft.com/download/8/4/a/84a35bf1-dafe-4ae8-82af-ad2ae20b6b14/directx_Jun2010_redist.exe" -OutFile $dxFile -UseBasicParsing

& "$env:SystemDrive\Program Files\7-Zip\7z.exe" x $dxFile -o"$env:SystemRoot\Temp\directx" -y | Out-Null
Start-Process -Wait "$env:SystemRoot\Temp\directx\DXSETUP.exe" -ArgumentList "/silent" -WindowStyle Hidden

# ------------------------------------------------------------------------------
# 7. REMOCAO DE BLOATWARES (UWP) E PREPARACAO PARA MODO SEGURO
# ------------------------------------------------------------------------------
Write-Host "[7/7] Removendo bloatwares e agendando reinicializacao..." -ForegroundColor Yellow

Get-AppXPackage -AllUsers | Where-Object {
    $_.Name -notlike '*CBS*' -and
    $_.Name -notlike '*Microsoft.AV1VideoExtension*' -and
    $_.Name -notlike '*Microsoft.AVCEncoderVideoExtension*' -and
    $_.Name -notlike '*Microsoft.HEIFImageExtension*' -and
    $_.Name -notlike '*Microsoft.HEVCVideoExtension*' -and
    $_.Name -notlike '*Microsoft.MPEG2VideoExtension*' -and
    $_.Name -notlike '*Microsoft.Paint*' -and
    $_.Name -notlike '*Microsoft.RawImageExtension*' -and
    $_.Name -notlike '*Microsoft.SecHealthUI*' -and
    $_.Name -notlike '*Microsoft.VP9VideoExtensions*' -and
    $_.Name -notlike '*Microsoft.WebMediaExtensions*' -and
    $_.Name -notlike '*Microsoft.WebpImageExtension*' -and
    $_.Name -notlike '*Microsoft.Windows.Photos*' -and
    $_.Name -notlike '*Microsoft.Windows.ShellExperienceHost*' -and
    $_.Name -notlike '*Microsoft.Windows.StartMenuExperienceHost*' -and
    $_.Name -notlike '*Microsoft.WindowsNotepad*' -and
    $_.Name -notlike '*Microsoft.WindowsStore*' -and
    $_.Name -notlike '*NVIDIACorp.NVIDIAControlPanel*' -and
    $_.Name -notlike '*windows.immersivecontrolpanel*'
} | Remove-AppxPackage -ErrorAction SilentlyContinue

# Configuracoes de inicializacao do Windows
cmd /c "reg add `"HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\PasswordLess\Device`" /v `"DevicePasswordLessBuildVersion`" /t REG_DWORD /d `"0`" /f >nul 2>&1"
cmd /c "reg add `"HKCU\Console\%%Startup`" /v `"DelegationConsole`" /t REG_SZ /d `"{B23D10C0-E52E-411E-9D5B-C09FDF709C7D}`" /f >nul 2>&1"
cmd /c "reg add `"HKCU\Console\%%Startup`" /v `"DelegationTerminal`" /t REG_SZ /d `"{B23D10C0-E52E-411E-9D5B-C09FDF709C7D}`" /f >nul 2>&1"

# Agendar stepone para rodar no Modo Seguro (Safe Mode)
cmd /c "reg add `"HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce`" /v `"*!stepone`" /t REG_SZ /d `"powershell.exe -nop -ep bypass -WindowStyle Maximized -f $env:SystemRoot\Temp\stepone.ps1`" /f >nul 2>&1"

# Agendar steptwo para rodar na reinicializacao normal apos o DDU
cmd /c "reg add `"HKCU\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce`" /v `"!steptwo`" /t REG_SZ /d `"powershell.exe -nop -ep bypass -WindowStyle Maximized -f $env:SystemRoot\Temp\steptwo.ps1`" /f >nul 2>&1"

# Configura boot em Modo Seguro
cmd /c "bcdedit /set {current} safeboot minimal >nul 2>&1"

Write-Host "`nEtapa 1 concluida com sucesso!" -ForegroundColor Green
Write-Host "O computador reiniciara em Modo Seguro em 5 segundos para a limpeza de drivers (DDU) e ajustes de seguranca." -ForegroundColor Yellow
Write-Host "REINICIANDO..." -ForegroundColor Red

Start-Sleep -Seconds 5
shutdown -r -t 00
